"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return async function gcrule(action,userID,threadID,callback){let _callback;if(typeof threadID==="function"){_callback=threadID;threadID=null}else if(typeof callback==="function"){_callback=callback}let resolvePromise,rejectPromise;const returnPromise=new Promise((resolve,reject)=>{resolvePromise=resolve;rejectPromise=reject});if(typeof _callback!="function"){_callback=(err,data)=>{if(err)return rejectPromise(err);resolvePromise(data)}}try{const validActions=["admin","unadmin"];action=action?action.toLowerCase():"";if(!validActions.includes(action)){_callback(null,{type:"error_gc_rule",error:`Invalid action. Must be one of: ${validActions.join(", ")}`});return returnPromise}if(!userID){_callback(null,{type:"error_gc_rule",error:"userID is required."});return returnPromise}if(!threadID){_callback(null,{type:"error_gc_rule",error:"threadID is required."});return returnPromise}if(!ctx.mqttClient||!ctx.mqttClient.connected){_callback(null,{type:"error_gc_rule",error:"Not connected to MQTT"});return returnPromise}const threadInfo=await api.getThreadInfo(threadID);if(!threadInfo){_callback(null,{type:"error_gc_rule",error:"Could not retrieve thread information."});return returnPromise}if(threadInfo.isGroup===false){_callback(null,{type:"error_gc_rule",error:"This feature is only for group chats."});return returnPromise}const adminIDs=threadInfo.adminIDs||[];const isCurrentlyAdmin=adminIDs.some(admin=>admin.id===userID);if(action==="admin"){if(isCurrentlyAdmin){_callback(null,{type:"error_gc_rule",error:`User is already an admin.`});return returnPromise}}else{if(!isCurrentlyAdmin){_callback(null,{type:"error_gc_rule",error:`User is not an admin.`});return returnPromise}}const isAdminStatus=action==="admin"?1:0;ctx.wsReqNumber=(ctx.wsReqNumber||0)+1;ctx.wsTaskNumber=(ctx.wsTaskNumber||0)+1;const queryPayload={thread_key:parseInt(threadID),contact_id:parseInt(userID),is_admin:isAdminStatus};const query={failure_count:null,label:"25",payload:JSON.stringify(queryPayload),queue_name:"admin_status",task_id:ctx.wsTaskNumber};const context={app_id:ctx.appID||"2220391788200892",payload:{epoch_id:parseInt(utils.generateOfflineThreadingID()),tasks:[query],version_id:"24631415369801570"},request_id:ctx.wsReqNumber,type:3};context.payload=JSON.stringify(context.payload);ctx.mqttClient.publish("/ls_req",JSON.stringify(context),{qos:1,retain:false},err=>{if(err)return _callback(err);const gcruleInfo={type:"gc_rule_update",threadID:threadID,userID:userID,action:action,senderID:ctx.userID,BotID:ctx.userID,timestamp:Date.now()};return _callback(null,gcruleInfo)})}catch(err){utils.error("gcrule",err);_callback(err instanceof Error?err:new Error(err.message||"An unknown error occurred."))}return returnPromise}};
